from taf.internal.cloud.lcmaas.client.lcmaas.v1 import CertsApi, CertIn


class CertsV1(object):
    def __init__(self, api_client):
        self.certs_api_v1 = CertsApi(api_client=api_client)

    def install_certs(self, peer_type, peer_name, cert_content):
        cert_content = 'cert=\n' + cert_content
        cert_data = CertIn(peer_type=peer_type, peer_name=peer_name, content=cert_content)
        return self.certs_api_v1.install_certs(cert_in=cert_data)
